 if(!['http:','https:'].includes(location.protocol)||staticSite){(document.querySelector('#create') as HTMLElement).hidden=true;(document.querySelector('#join') as HTMLElement).hidden=true;(document.querySelector('#account-button') as HTMLElement).hidden=true;document.querySelector('.save-info')!.textContent='HTML5 ออฟไลน์ · เปิดไฟล์แล้วเล่นได้ทันที · บันทึกในเบราว์เซอร์ · Co-op ใช้ชุดเซิร์ฟเวอร์'}
