 document.querySelectorAll('[data-move]').forEach(e=>{e.addEventListener('pointerdown',ev=>{ev.preventDefault();const [x,y]=(e as HTMLElement).dataset.move!.split(',').map(Number);send({type:'input',x,y});(e as HTMLElement).setPointerCapture((ev as PointerEvent).pointerId)});e.addEventListener('pointerup',()=>send({type:'input',x:0,y:0}));e.addEventListener('pointercancel',()=>send({type:'input',x:0,y:0}))});document.querySelector('#touch-dodge')!.addEventListener('click',()=>send({type:'dodge'}));
