 for(let i=0;i<20;i++){const entry=barEntry(p.hotbar[i],c);const ready=entry.type==='gem'?p.gemCooldowns[entry.gemId]||0:entry.type==='utility'?(entry.id==='dodge'&&p.dodgeCharges===0?Math.min(...p.dodgeTimers):0):p.skillCooldowns?.[entry.skillIndex]||0;const remain=Math.max(0,ready-state.time);set('bar-cd-'+i,remain>.05?remain.toFixed(1):'');const el=document.querySelector(`[data-bar="${i}"]`);if(el){el.classList.toggle('no-resource',entry.cost*combatStats(p,c).cost>p.mp||(entry.id==='potion'&&p.potions===0));el.classList.toggle('utility-active',(entry.id==='auto'&&p.auto)||(entry.id==='block'&&p.blocking)||(entry.id==='lock'&&!!p.lockId));}if(entry.id==='potion')set('bar-tip-'+i,p.potions+'');if(entry.type==='gem'&&el){el.classList.toggle('no-resource',Boolean(gemUsability(p,gemById(entry.gemId)))||gemProfile(p,gemById(entry.gemId)).mana>p.mp);el.classList.toggle('utility-active',p.activeAuras.includes(entry.gemId))}}
