function drawMinimap(){const cv=document.querySelector('#minimap') as HTMLCanvasElement,p=player();if(!cv||!p)return;const c=cv.getContext('2d')!;c.fillStyle='#243b3e';c.fillRect(0,0,140,105);const radius=1400,sx=(x:number)=>(x-p.x)/radius*70+70,sy=(y:number)=>(y-p.y)/radius*52+52;c.strokeStyle='#a1885c88';c.lineWidth=2;c.beginPath();for(let i=1;i<LANDMARKS.length;i++){c.moveTo(sx(LANDMARKS[i-1].x),sy(LANDMARKS[i-1].y));c.lineTo(sx(LANDMARKS[i].x),sy(LANDMARKS[i].y))}c.stroke();if(state.zone===0&&p.x<2300&&p.y<1900){c.fillStyle='#647579';for(const r of [[680,480,150,130],[1070,400,180,150],[1260,970,160,120]])c.fillRect(sx(r[0]),sy(r[1]),r[2]/radius*70,r[3]/radius*52)}for(const l of LANDMARKS){c.fillStyle=p.discovered.includes(landmarkKey(state.zone,l.id))?'#78e6d9':'#a99976';c.fillRect(sx(l.x)-2,sy(l.y)-2,4,4)}for(const e of state.enemies){c.fillStyle=e.boss?'#dc866b':'#af9a71';c.fillRect(sx(e.x),sy(e.y),e.boss?4:2,e.boss?4:2)}for(const q of Object.values(state.players) as any[]){c.fillStyle=q.id===myId?'#fff3cd':'#75d7e6';c.beginPath();c.arc(sx(q.x),sy(q.y),3,0,Math.PI*2);c.fill()}}
