 this.input.on('pointermove',(pt:Phaser.Input.Pointer)=>{aim={x:pt.worldX,y:pt.worldY}});this.input.on('pointerdown',(pt:Phaser.Input.Pointer)=>{if(!state||modal||!player())return;aim={x:pt.worldX,y:pt.worldY};pendingNpc=null;const shift=this.input.keyboard!.addKey('SHIFT').isDown;if(pt.rightButtonDown()){cast(0,true);return}if(shift){this.pointerHeld=true;cast(0);return}const enemy=state.enemies.filter((e:any)=>e.hp>0&&Math.hypot(e.x-aim.x,e.y-28-aim.y)<(e.boss?75:35)).sort((a:any,b:any)=>Math.hypot(a.x-aim.x,a.y-aim.y)-Math.hypot(b.x-aim.x,b.y-aim.y))[0];if(enemy){send({type:'target',id:enemy.id});return}const npc=worldNpcs(state.zone).find(n=>Math.hypot(n.x-aim.x,n.y-30-aim.y)<45)||null;if(npc){pendingNpc=npc;send({type:'move',x:npc.x,y:npc.y+50});return}send({type:'move',x:aim.x,y:aim.y});});this.input.on('pointerup',()=>this.pointerHeld=false);
