 for(const e of state.enemies){visible.add(e.id);const a=this.actor(e.id,e.boss?'boss':'enemy');a.setVisible(true).setPosition(e.x,e.y).setDepth(e.y);const g=(a as any).body as Phaser.GameObjects.Graphics;g.clear();const monster=(a as any).monster as Phaser.GameObjects.Image;monster.setTexture((e.boss?'farm-boss-':'farm-monster-')+Math.max(0,MAPS[state.zone].biome)).setDisplaySize(e.boss?125:45,e.boss?115:e.kind===1?45:40);monster.y=Math.sin(t*(e.boss?2:5)+e.x)*2;monster.setTint(e.hurtUntil>t?0xffe9be:e.frozenUntil>t?0xb0e8ff:e.brokenUntil>t?0xdfd0a1:e.slow>t?0xbbddff:0xffffff);const hp=(a as any).hp as Phaser.GameObjects.Graphics;hp.clear();if(e.hp<e.maxHp){hp.fillStyle(0x607654,.6).fillRect(-20,-(e.boss?112:43),40,4);hp.fillStyle(0xe8ab82).fillRect(-20,-(e.boss?112:43),40*e.hp/e.maxHp,4)}if(e.poise>0){hp.fillStyle(0x68745f,.4).fillRect(-20,-(e.boss?106:37),40,2);hp.fillStyle(0xeacb84).fillRect(-20,-(e.boss?106:37),40*e.poise/100,2)}(a as any).label.setText(e.frozenUntil>t?'❄':e.brokenUntil>t?'✧':e.name||'')}
